pub fn linear_search(nums: Vec<i32>, target: i32) -> i32 {
    for (i, &num) in nums.iter().enumerate() {
        if num == target {
            // i is usize, but problem guarantees nums.len() < 2,147,483,648,
            // so casting to i32 is safe.
            return i as i32;
        }
    }
    // target not found
    -1
}

